sys_script_include.script:
var get_certificate_groups = Class.create();
get_certificate_groups.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    checkgroups: function() {
        try {
            url = gs.getProperty("x_avx_appviewx_aut.URL");
            mid_server = gs.getProperty("x_avx_appviewx_aut.MID Server Name");
            var user_name = gs.getUserName(); // Username
            var email = gs.getUser().getEmail();
            var policy = this.getParameter("sysparm_policy");
            var ca_tag_name = this.getParameter("sysparm_ca_tag_name");
            var gr = new GlideRecordSecure('x_avx_appviewx_aut_clm_settings');
            gr.addQuery('ca_tag_name', ca_tag_name);
            gr.query();
            var values = {};
            if (!gr.hasNext()) {
                throw "Could not find CA Tag with the name - " + ca_tag_name;
            }
            while (gr.next()) {
                var selection = gr.getValue('certificate_group_selection');
            }
            var company = this.getParameter("sysparm_company");
            var client_id;
            var script_include_call = new appviewx_oauth_token_generation();
            var token_generation = script_include_call.TestConnection(client_id, company);
            if (token_generation.length == 2 && token_generation[0] == 200) {
                var parse_response = JSON.parse(token_generation[1]);
                var token = parse_response['response'];
            } else {
                throw "Error while generating the token";
            }
            var r = new sn_ws.RESTMessageV2();
            var payload = {
                "payload": {
                    "hook": {
                        "name": "ServiceNow - Get Certificate Groups"
                    },
                    "input": {
                        "user_name": user_name,
                        "email": email,
                        "policy": policy,
                        "selection": selection
                    }
                }
            };

            var retry_count = 0;
            if (gs.getProperty("glide.sys.domain.partitioning") == 'true') {
                var res_obj = new GlideRecordSecure('x_avx_appviewx_aut_connection_settings_table');
                res_obj.addQuery('company', company);
                res_obj.query();
                if (!res_obj.hasNext()) {
                    throw "Could not find AppViewX instance url to fetch the details.";
                }
                while (res_obj.next()) {
                    var url = res_obj.getValue('instance_url') || '';
                    var mid_server = res_obj.getValue('mid_server') || '';
                    var cmdb_sync = res_obj.getDisplayValue('enable_appviewx_inventory_sync') || "false";
                }
            } else {
                url = gs.getProperty("x_avx_appviewx_aut.URL");
                mid_server = gs.getProperty("x_avx_appviewx_aut.MID Server Name");
                cmdb_sync = gs.getProperty("x_avx_appviewx_aut.CMDB Sync");
            }
            while (retry_count < 5) {
                if (mid_server != "") {
                    r.setMIDServer(mid_server);
                    r.setEccParameter('skip_sensor', 'true');
                }
                r.setHttpMethod("post");
                r.setRequestHeader("token", token);
                r.setRequestHeader('User-Agent', 'snow');
                r.setRequestHeader("Content-Type", "application/json");
                r.setEndpoint(url + "/avxapi/execute-hook?&gwsource=web");
                r.setRequestBody(JSON.stringify(payload));
                var response = r.executeAsync();
                var responseBody, responseMessage;
                if (response.haveError()) {
                    responseBody = response.getBody();
                    try {
                        var res = JSON.parse(responseBody);
                        message = res.message;
                    } catch (err) {
                        message = responseBody;
                    }
                } else {
                    responseBody = response.getBody();
                    responseBody = JSON.parse(responseBody);
                    return JSON.stringify(responseBody);
                }
                if (retry_count == 4) {
                    throw JSON.stringify(message) || "Couldn't get Cert Groups " + selection;
                }
                retry_count = retry_count + 1;
            }

        } catch (error) {
            var log = new GlideRecordSecure('x_avx_appviewx_aut_logs');
            gs.addErrorMessage(JSON.stringify(responseBody));
            var plugin_table_log = gs.getProperty("x_avx_appviewx_aut.Log Purge");
            if (plugin_table_log == 'true') {
                log.initialize();
                log.level = 'Error';
                log.script = 'get_certificate_groups';
                log.application = 'AppViewX';
                log.message = 'Error occured while getting the Certificate Groups from appviewx  -  ' + error;
                log.insert();
            } else {
                gs.error('Error occured while getting the Certificate Groups from appviewx  -  ' + error + '\n\n Script : get_certificate_groups');
            }

            return error;
        }
    },

    type: 'get_certificate_groups'
});
